package jp.nw.controller;
import java.io.*;import java.sql.*;import java.time.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import jp.nw.entity.UserEntity;import jp.nw.parts.DBBase;
@WebServlet("/AttendanceAction")
public class AttendanceActionController extends HttpServlet{
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{UserEntity u=(UserEntity)req.getSession().getAttribute("loginUser");String action=req.getParameter("action");DBBase db=new DBBase();try(Connection c=db.getConnection()){if("clockIn".equals(action)){try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance_record(user_id,work_date,clock_in,work_type) SELECT ?,CURDATE(),CURTIME(),'OFFICE' WHERE NOT EXISTS(SELECT 1 FROM attendance_month_close WHERE user_id=? AND target_month=DATE_FORMAT(CURDATE(),'%Y-%m-01')) ON DUPLICATE KEY UPDATE clock_in=COALESCE(clock_in,CURTIME())")){p.setString(1,u.getUserId());p.setString(2,u.getUserId());p.executeUpdate();}}else if("clockOut".equals(action)){try(PreparedStatement p=c.prepareStatement("UPDATE attendance_record a SET clock_out=CURTIME(),overtime_minutes=GREATEST(TIMESTAMPDIFF(MINUTE,clock_in,CURTIME())-break_minutes-480,0) WHERE user_id=? AND work_date=CURDATE() AND approval_status IN ('DRAFT','REJECTED') AND NOT EXISTS(SELECT 1 FROM attendance_month_close m WHERE m.user_id=a.user_id AND m.target_month=DATE_FORMAT(a.work_date,'%Y-%m-01'))")){p.setString(1,u.getUserId());if(p.executeUpdate()==0)throw new IllegalArgumentException("先に出勤を打刻するか、締め状態を確認してください。");}}else if(("close".equals(action)||"reopen".equals(action))&&"1".equals(u.getPermission())){YearMonth month=YearMonth.parse(req.getParameter("month"));if("close".equals(action)){try(PreparedStatement p=c.prepareStatement("INSERT IGNORE INTO attendance_month_close(user_id,target_month,closed_by_id) VALUES(?,?,?)")){p.setString(1,u.getUserId());p.setObject(2,month.atDay(1));p.setString(3,u.getUserId());p.executeUpdate();}}else try(PreparedStatement p=c.prepareStatement("DELETE FROM attendance_month_close WHERE user_id=? AND target_month=?")){p.setString(1,u.getUserId());p.setObject(2,month.atDay(1));p.executeUpdate();}}req.getSession().setAttribute("attendanceFlash","処理が完了しました。");req.getSession().setAttribute("attendanceFlashType","success");}catch(Exception e){req.getSession().setAttribute("attendanceFlash",e.getMessage());req.getSession().setAttribute("attendanceFlashType","error");}res.sendRedirect(req.getContextPath()+"/WorkManagement");}
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{UserEntity u=(UserEntity)req.getSession().getAttribute("loginUser");YearMonth m;try{m=YearMonth.parse(req.getParameter("month"));}catch(Exception e){m=YearMonth.now();}res.setCharacterEncoding("UTF-8");res.setContentType("text/csv; charset=UTF-8");res.setHeader("Content-Disposition","attachment; filename=attendance-"+m+".csv");PrintWriter w=res.getWriter();w.write('\ufeff');w.println("日付,勤務区分,出勤,退勤,休憩(分),残業(分),承認状態,備考");DBBase db=new DBBase();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT work_date,attendance_type,clock_in,clock_out,break_minutes,overtime_minutes,approval_status,note FROM attendance_record WHERE user_id=? AND work_date>=? AND work_date<? ORDER BY work_date")){p.setString(1,u.getUserId());p.setObject(2,m.atDay(1));p.setObject(3,m.plusMonths(1).atDay(1));try(ResultSet r=p.executeQuery()){while(r.next())w.println(csv(r.getString(1))+","+csv(r.getString(2))+","+csv(r.getString(3))+","+csv(r.getString(4))+","+r.getInt(5)+","+r.getInt(6)+","+csv(r.getString(7))+","+csv(r.getString(8)));}}catch(SQLException e){throw new IOException(e);}}
 private String csv(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
}
